[31] export function buildPaginationOptions(params: PaginationParams) {
[32]   const page = params.page && params.page > 0 ? params.page : 1;
[33]   const pageSize = params.pageSize && params.pageSize > 0 ? params.pageSize : 10;
[34]   const skip = (page - 1) * pageSize;
[35]   const take = pageSize;
[36]   return { skip, take, page, pageSize };
[37] }
[38] 
[39] /**
[40]  * 创建分页响应
[41]  */
[42] export function createPaginatedResponse<T>(
[43]   items: T[],
[44]   total: number,
[45]   page: number,
[46]   pageSize: number
[47] ): PaginatedResult<T> {
[48]   const totalPages = Math.ceil(total / pageSize);
[49]   return {
[50]     items,
[51]     total,
[52]     page,
[53]     pageSize,
[54]     totalPages,
[55]     hasNext: page < totalPages,
[56]     hasPrev: page > 1,
[57]   };
[58] }
[59] 
[60] /**
[61]  * 全文搜索参数
[62]  */
[63] export interface FullTextSearchParams {
[64]   query: string;
[65]   page?: number;
[66]   pageSize?: number;
[67]   includeDrafts?: boolean; // 是否包含草稿
[68] }
[69] 
[70] /**
[71]  * 全文搜索结果项
[72]  */
[73] export interface SearchResultItem {
[74]   id: number;
[75]   title: string;
[76]   excerpt: string | null;
[77]   content: string;
[78]   snippet: string;
[79]   rank: number;
[80] }
[81] 
[82] /**
[83]  * 执行全文搜索
[84]  */
[85] export async function fullTextSearch(
[86]   params: FullTextSearchParams
[87] ): Promise<PaginatedResult<SearchResultItem>> {
[88]   const { query, page = 1, pageSize = 10, includeDrafts = false } = params;
[89]   const { skip, take } = buildPaginationOptions({ page, pageSize });
[90] 
[91]   // 构建MATCH表达式
[92]   const searchQuery = query.trim();
[93]   if (!searchQuery) {
[94]     return createPaginatedResponse([], 0, page, pageSize);
[95]   }
[96] 
[97]   // 首先获取匹配的博客ID和排名
[98]   const matched = (await prisma.$queryRaw`
[99]     SELECT blogId, rank
[100]     FROM BlogFTS
[101]     WHERE BlogFTS MATCH ${searchQuery}
[102]     ORDER BY rank
[103]     LIMIT ${take} OFFSET ${skip}
[104]   `) as Array<{ blogId: bigint; rank: number }>;
[105] 
[106]   // 获取总匹配数
[107]   const totalResult = (await prisma.$queryRaw`
[108]     SELECT COUNT(*) as total
[109]     FROM BlogFTS
[110]     WHERE BlogFTS MATCH ${searchQuery}
[111]   `) as Array<{ total: bigint }>;
[112]   const total = Number(totalResult[0].total);
[113] 
[114]   if (matched.length === 0) {
[115]     return createPaginatedResponse([], total, page, pageSize);
[116]   }
[117] 
[118]   // 获取博客详情和片段
[119]   const blogIds = matched.map((m) => Number(m.blogId)); // convert BigInt to number
[120]   const rankMap = new Map(matched.map((m) => [Number(m.blogId), m.rank]));
[121] 
[122]   const blogs = await prisma.blog.findMany({
[123]     where: {
[124]       id: { in: blogIds },
[125]       status: includeDrafts ? undefined : BlogStatus.PUBLISHED,
[126]     },
[127]     select: {
[128]       id: true,
[129]       title: true,
[130]       excerpt: true,
[131]       content: true,
[132]     },
[133]   });
[134] 
[135]   // 为每个博客获取搜索片段
[136]   const snippets = (await prisma.$queryRaw`
[137]     SELECT blogId, snippet(BlogFTS, 2, '<b>', '</b>', '...', 80) as snippet
[138]     FROM BlogFTS
[139]     WHERE blogId IN (${blogIds.join(',')}) AND BlogFTS MATCH ${searchQuery}
[140]   `) as Array<{ blogId: bigint; snippet: string }>;
[141] 
[142]   const snippetMap = new Map(snippets.map((s) => [Number(s.blogId), s.snippet]));
[143] 
[144]   // 构建结果项
[145]   const items: SearchResultItem[] = blogs.map((blog) => ({
[146]     id: blog.id,
[147]     title: blog.title,
[148]     excerpt: blog.excerpt,
[149]     content: blog.content,
[150]     snippet: snippetMap.get(blog.id) || '',
[151]     rank: rankMap.get(blog.id) || 0,
[152]   }));
[153] 
[154]   // 按原始排名排序
[155]   items.sort((a, b) => a.rank - b.rank);
[156] 
[157]   return createPaginatedResponse(items, total, page, pageSize);
[158] }

