import { BlogStatus } from '@prisma/client';
import prisma from '../db';
import { BadRequestError, NotFoundError } from '../utils/AppError';

/**
 * 搜索博客输入参数
 */
export interface SearchBlogsInput {
  query: string; // 搜索关键词
  categoryId?: number; // 分类ID
  tagIds?: number[]; // 标签ID数组
  authorId?: number; // 作者ID
  status?: BlogStatus; // 博客状态
  startDate?: Date; // 开始日期
  endDate?: Date; // 结束日期
  sort?: 'relevance' | 'createdAt' | 'updatedAt' | 'publishedAt' | 'viewCount'; // 排序字段
  order?: 'asc' | 'desc'; // 排序方向
  page?: number; // 页码（从1开始）
  limit?: number; // 每页数量
}

/**
 * 博客搜索结果项
 */
export interface SearchBlogResult {
  id: number;
  title: string;
  excerpt: string | null;
  content: string;
  snippet: string; // 高亮片段
  rank: number; // 相关性评分
  author: {
    id: number;
    name: string;
    email: string;
    avatar: string | null;
  };
  category: {
    id: number;
    name: string;
    slug: string;
  } | null;
  tags: {
    id: number;
    name: string;
    slug: string;
  }[];
  status: BlogStatus;
  createdAt: Date;
  updatedAt: Date;
  publishedAt: Date | null;
  viewCount: number;
  _count: {
    comments: number;
    likes: number;
    bookmarks: number;
  };
}

/**
 * 分页搜索结果
 */
export interface PaginatedSearchResult {
  blogs: SearchBlogResult[];
  pagination: {
    page: number;
    limit: number;
    total: number;
    totalPages: number;
    hasNext: boolean;
    hasPrev: boolean;
  };
}

/**
 * 搜索建议项
 */
export interface SearchSuggestion {
  type: 'keyword' | 'tag' | 'category';
  text: string;
  count?: number;
}

/**
 * 搜索历史项
 */
export interface SearchHistoryItem {
  id: number;
  query: string;
  createdAt: Date;
}

/**
 * 热门搜索项
 */
export interface PopularSearchItem {
  query: string;
  count: number;
  lastSearched: Date;
}

/**
 * 搜索博客文章（全文搜索 + 筛选）
 */
export const searchBlogs = async (input: SearchBlogsInput): Promise<PaginatedSearchResult> => {
  const {
    query,
    categoryId,
    tagIds,
    authorId,
    status = BlogStatus.PUBLISHED,
    startDate,
    endDate,
    sort = 'relevance',
    order = 'desc',
    page = 1,
    limit = 10,
  } = input;

  // 验证查询关键词
  if (!query || query.trim().length === 0) {
    throw new BadRequestError('搜索关键词是必需的');
  }

  // 构建MATCH表达式，支持FTS5语法
  const searchQuery = query.trim();

  // 首先通过FTS5获取匹配的博客ID和排名
  // 使用原始SQL查询BlogFTS表
  const matchCondition = `BlogFTS MATCH ${prisma.$escape(searchQuery)}`;

  // 构建基础查询：获取匹配的博客ID和排名
  let ftsQuery = `
    SELECT blogId, rank
    FROM BlogFTS
    WHERE ${matchCondition}
  `;

  // 如果有额外的筛选条件，我们需要在获取博客ID后进行筛选
  // 先获取所有匹配的ID
  const ftsResult = await prisma.$queryRawUnsafe<Array<{ blogId: bigint; rank: number }>>(ftsQuery);

  if (ftsResult.length === 0) {
    return {
      blogs: [],
      pagination: {
        page,
        limit,
        total: 0,
        totalPages: 0,
        hasNext: false,
        hasPrev: false,
      },
    };
  }

  const blogIds = ftsResult.map(r => Number(r.blogId));
  const rankMap = new Map(ftsResult.map(r => [Number(r.blogId), r.rank]));

  // 构建Prisma查询条件
  const where: any = {
    id: { in: blogIds },
    status,
  };

  if (categoryId) {
    where.categoryId = categoryId;
  }

  if (authorId) {
    where.authorId = authorId;
  }

  if (tagIds && tagIds.length > 0) {
    where.blogTags = {
      some: {
        tagId: { in: tagIds },
      },
    };
  }

  if (startDate || endDate) {
    where.createdAt = {};
    if (startDate) {
      where.createdAt.gte = startDate;
    }
    if (endDate) {
      where.createdAt.lte = endDate;
    }
  }

  // 计算总数（应用筛选条件后）
  const total = await prisma.blog.count({ where });

  // 计算总页数
  const totalPages = Math.ceil(total / limit);

  // 确定排序方式
  let orderBy: any = {};
  if (sort === 'relevance') {
    // 按相关性排序：需要自定义排序逻辑
    // 我们将按rank升序（FTS5 rank值越小越相关），但需要与筛选后的博客ID匹配
    // 通过应用筛选后，我们仍然需要按rank排序，但rankMap只包含匹配的博客
    // 我们将获取博客后手动排序
  } else {
    orderBy[sort] = order;
  }

  // 获取博客列表
  const blogs = await prisma.blog.findMany({
    where,
    skip: (page - 1) * limit,
    take: limit,
    orderBy: sort === 'relevance' ? undefined : orderBy,
    include: {
      author: {
        select: {
          id: true,
          name: true,
          email: true,
          avatar: true,
        },
      },
      category: {
        select: {
          id: true,
          name: true,
          slug: true,
        },
      },
      blogTags: {
        include: {
          tag: {
            select: {
              id: true,
              name: true,
              slug: true,
            },
          },
        },
      },
      _count: {
        select: {
          comments: true,
          likes: true,
          bookmarks: true,
        },
      },
    },
  });

  // 获取高亮片段
  const snippets = await prisma.$queryRawUnsafe<Array<{ blogId: bigint; snippet: string }>>(`
    SELECT blogId, snippet(BlogFTS, 2, '<b>', '</b>', '...', 120) as snippet
    FROM BlogFTS
    WHERE blogId IN (${blogIds.join(',')}) AND ${matchCondition}
  `);

  const snippetMap = new Map(snippets.map(s => [Number(s.blogId), s.snippet]));

  // 格式化博客数据
  const formattedBlogs: SearchBlogResult[] = blogs.map(blog => ({
    id: blog.id,
    title: blog.title,
    excerpt: blog.excerpt,
    content: blog.content,
    snippet: snippetMap.get(blog.id) || '',
    rank: rankMap.get(blog.id) || 0,
    author: blog.author,
    category: blog.category,
    tags: blog.blogTags.map(blogTag => blogTag.tag),
    status: blog.status,
    createdAt: blog.createdAt,
    updatedAt: blog.updatedAt,
    publishedAt: blog.publishedAt,
    viewCount: blog.viewCount,
    _count: blog._count,
  }));

  // 如果是按相关性排序，手动排序
  if (sort === 'relevance') {
    formattedBlogs.sort((a, b) => {
      const rankA = a.rank;
      const rankB = b.rank;
      return order === 'asc' ? rankA - rankB : rankB - rankA;
    });
  }

  return {
    blogs: formattedBlogs,
    pagination: {
      page,
      limit,
      total,
      totalPages,
      hasNext: page < totalPages,
      hasPrev: page > 1,
    },
  };
};

/**
 * 获取搜索建议
 */
export const getSearchSuggestions = async (query: string): Promise<SearchSuggestion[]> => {
  const suggestions: SearchSuggestion[] = [];

  if (!query || query.trim().length === 0) {
    return suggestions;
  }

  const searchQuery = query.trim();

  // 1. 从搜索历史中获取建议（最近5条）
  const recentSearches = await prisma.searchHistory.findMany({
    where: {
      query: {
        contains: searchQuery,
        mode: 'insensitive',
      },
    },
    orderBy: {
      createdAt: 'desc',
    },
    take: 5,
    distinct: ['query'],
  });

  recentSearches.forEach(history => {
    suggestions.push({
      type: 'keyword',
      text: history.query,
    });
  });

  // 2. 从标签中获取建议
  const tagSuggestions = await prisma.tag.findMany({
    where: {
      name: {
        contains: searchQuery,
        mode: 'insensitive',
      },
    },
    take: 5,
  });

  tagSuggestions.forEach(tag => {
    suggestions.push({
      type: 'tag',
      text: tag.name,
      count: tag.blogCount,
    });
  });

  // 3. 从分类中获取建议
  const categorySuggestions = await prisma.category.findMany({
    where: {
      name: {
        contains: searchQuery,
        mode: 'insensitive',
      },
    },
    take: 5,
  });

  categorySuggestions.forEach(category => {
    suggestions.push({
      type: 'category',
      text: category.name,
    });
  });

  // 去重（相同文本和类型）
  const seen = new Set<string>();
  return suggestions.filter(suggestion => {
    const key = `${suggestion.type}:${suggestion.text}`;
    if (seen.has(key)) {
      return false;
    }
    seen.add(key);
    return true;
  });
};

/**
 * 记录搜索历史（内部使用）
 */
export const recordSearchHistory = async (userId: number, query: string): Promise<void> => {
  try {
    await prisma.searchHistory.create({
      data: {
        userId,
        query: query.trim(),
      },
    });
  } catch (error) {
    // 忽略错误，搜索历史记录不是关键功能
    console.error('Failed to record search history:', error);
  }
};

/**
 * 获取用户的搜索历史
 */
export const getUserSearchHistory = async (
  userId: number,
  page: number = 1,
  limit: number = 10
) => {
  const skip = (page - 1) * limit;

  const [history, total] = await Promise.all([
    prisma.searchHistory.findMany({
      where: { userId },
      orderBy: { createdAt: 'desc' },
      skip,
      take: limit,
      select: {
        id: true,
        query: true,
        createdAt: true,
      },
    }),
    prisma.searchHistory.count({ where: { userId } }),
  ]);

  const totalPages = Math.ceil(total / limit);

  return {
    history: history as SearchHistoryItem[],
    pagination: {
      page,
      limit,
      total,
      totalPages,
      hasNext: page < totalPages,
      hasPrev: page > 1,
    },
  };
};

/**
 * 获取热门搜索关键词
 */
export const getPopularSearches = async (
  period: 'today' | 'week' | 'month' | 'all' = 'today',
  limit: number = 10
): Promise<PopularSearchItem[]> => {
  // 构建日期筛选条件
  let dateFilter = '';
  const now = new Date();

  switch (period) {
    case 'today':
      const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());
      dateFilter = `AND createdAt >= '${todayStart.toISOString()}'`;
      break;
    case 'week':
      const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
      dateFilter = `AND createdAt >= '${weekAgo.toISOString()}'`;
      break;
    case 'month':
      const monthAgo = new Date(now.getFullYear(), now.getMonth() - 1, now.getDate());
      dateFilter = `AND createdAt >= '${monthAgo.toISOString()}'`;
      break;
    case 'all':
    default:
      dateFilter = '';
  }

  // 使用原始SQL进行聚合查询
  const popularSearches = await prisma.$queryRawUnsafe<Array<{ query: string; count: bigint; lastSearched: Date }>>(`
    SELECT query, COUNT(*) as count, MAX(createdAt) as lastSearched
    FROM SearchHistory
    WHERE query IS NOT NULL AND query != '' ${dateFilter}
    GROUP BY query
    ORDER BY count DESC, lastSearched DESC
    LIMIT ${limit}
  `);

  return popularSearches.map(item => ({
    query: item.query,
    count: Number(item.count),
    lastSearched: item.lastSearched,
  }));
};

/**
 * 删除单条搜索历史记录
 */
export const deleteSearchHistory = async (historyId: number, userId: number): Promise<void> => {
  const history = await prisma.searchHistory.findUnique({
    where: { id: historyId },
  });

  if (!history) {
    throw new NotFoundError('搜索历史记录不存在');
  }

  // 确保用户只能删除自己的搜索历史
  if (history.userId !== userId) {
    throw new BadRequestError('您只能删除自己的搜索历史记录');
  }

  await prisma.searchHistory.delete({
    where: { id: historyId },
  });
};

/**
 * 清空用户的搜索历史
 */
export const clearSearchHistory = async (userId: number): Promise<void> => {
  await prisma.searchHistory.deleteMany({
    where: { userId },
  });
};

