import { Router } from 'express';
import * as searchController from '../controllers/search.controller';
import * as searchValidation from '../validations/search.validation';
import { requireAuth } from '../middleware/auth';
import { validate } from '../middleware/validate';

const router = Router();

/**
 * @route GET /api/search/blogs
 * @desc 搜索博客文章（全文搜索 + 高级筛选）
 * @access Public
 */
router.get(
  '/blogs',
  searchValidation.searchBlogsValidation,
  validate,
  searchController.searchBlogs
);

/**
 * @route GET /api/search/suggestions
 * @desc 获取搜索建议（自动完成）
 * @access Public
 */
router.get(
  '/suggestions',
  searchValidation.searchSuggestionsValidation,
  validate,
  searchController.searchSuggestions
);

/**
 * @route GET /api/search/history
 * @desc 获取当前用户的搜索历史
 * @access Private
 */
router.get(
  '/history',
  requireAuth,
  searchValidation.searchHistoryValidation,
  validate,
  searchController.searchHistory
);

/**
 * @route GET /api/search/popular
 * @desc 获取热门搜索关键词
 * @access Public
 */
router.get(
  '/popular',
  searchValidation.popularSearchesValidation,
  validate,
  searchController.getPopularSearches
);

/**
 * @route DELETE /api/search/history/:id
 * @desc 删除单条搜索历史记录
 * @access Private
 */
router.delete(
  '/history/:id',
  requireAuth,
  searchValidation.deleteSearchHistoryValidation,
  validate,
  searchController.deleteSearchHistory
);

/**
 * @route DELETE /api/search/history
 * @desc 清空当前用户的搜索历史
 * @access Private
 */
router.delete(
  '/history',
  requireAuth,
  searchController.clearSearchHistory
);

export default router;

