[1] import { BlogStatus } from '@prisma/client';
[2] import prisma from '../db';
[3] import { BadRequestError, NotFoundError } from '../utils/AppError';
[4] 
[5] /**
[6]  * 搜索博客输入参数
[7]  */
[8] export interface SearchBlogsInput {
[9]   query: string; // 搜索关键词
[10]   categoryId?: number; // 分类ID
[11]   tagIds?: number[]; // 标签ID数组
[12]   authorId?: number; // 作者ID
[13]   status?: BlogStatus; // 博客状态
[14]   startDate?: Date; // 开始日期
[15]   endDate?: Date; // 结束日期
[16]   sort?: 'relevance' | 'createdAt' | 'updatedAt' | 'publishedAt' | 'viewCount'; // 排序字段
[17]   order?: 'asc' | 'desc'; // 排序方向
[18]   page?: number; // 页码（从1开始）
[19]   limit?: number; // 每页数量
[20] }
[21] 
[22] /**
[23]  * 博客搜索结果项
[24]  */
[25] export interface SearchBlogResult {
[26]   id: number;
[27]   title: string;
[28]   excerpt: string | null;
[29]   content: string;
[30]   snippet: string; // 高亮片段
[31]   rank: number; // 相关性评分
[32]   author: {
[33]     id: number;
[34]     name: string;
[35]     email: string;
[36]     avatar: string | null;
[37]   };
[38]   category: {
[39]     id: number;
[40]     name: string;
[41]     slug: string;
[42]   } | null;
[43]   tags: {
[44]     id: number;
[45]     name: string;
[46]     slug: string;
[47]   }[];
[48]   status: BlogStatus;
[49]   createdAt: Date;
[50]   updatedAt: Date;
[51]   publishedAt: Date | null;
[52]   viewCount: number;
[53]   _count: {
[54]     comments: number;
[55]     likes: number;
[56]     bookmarks: number;
[57]   };
[58] }
[59] 
[60] /**
[61]  * 分页搜索结果
[62]  */
[63] export interface PaginatedSearchResult {
[64]   blogs: SearchBlogResult[];
[65]   pagination: {
[66]     page: number;
[67]     limit: number;
[68]     total: number;
[69]     totalPages: number;
[70]     hasNext: boolean;
[71]     hasPrev: boolean;
[72]   };
[73] }
[74] 
[75] /**
[76]  * 搜索建议项
[77]  */
[78] export interface SearchSuggestion {
[79]   type: 'keyword' | 'tag' | 'category';
[80]   text: string;
[81]   count?: number;
[82] }
[83] 
[84] /**
[85]  * 搜索历史项
[86]  */
[87] export interface SearchHistoryItem {
[88]   id: number;
[89]   query: string;
[90]   createdAt: Date;
[91] }
[92] 
[93] /**
[94]  * 热门搜索项
[95]  */
[96] export interface PopularSearchItem {
[97]   query: string;
[98]   count: number;
[99]   lastSearched: Date;
[100] }
[101] 
[102] /**
[103]  * 搜索博客文章（全文搜索 + 筛选）
[104]  */
[105] export const searchBlogs = async (input: SearchBlogsInput): Promise<PaginatedSearchResult> => {
[106]   const {
[107]     query,
[108]     categoryId,
[109]     tagIds,
[110]     authorId,
[111]     status = BlogStatus.PUBLISHED,
[112]     startDate,
[113]     endDate,
[114]     sort = 'relevance',
[115]     order = 'desc',
[116]     page = 1,
[117]     limit = 10,
[118]   } = input;
[119] 
[120]   // 验证查询关键词
[121]   if (!query || query.trim().length === 0) {
[122]     throw new BadRequestError('搜索关键词是必需的');
[123]   }
[124] 
[125]   // 构建MATCH表达式，支持FTS5语法
[126]   const searchQuery = query.trim();
[127]   
[128]   // 首先通过FTS5获取匹配的博客ID和排名
[129]   // 使用原始SQL查询BlogFTS表
[130]   const matchCondition = `BlogFTS MATCH ${prisma.$escape(searchQuery)}`;
[131]   
[132]   // 构建基础查询：获取匹配的博客ID和排名
[133]   let ftsQuery = `
[134]     SELECT blogId, rank
[135]     FROM BlogFTS
[136]     WHERE ${matchCondition}
[137]   `;
[138]   
[139]   // 如果有额外的筛选条件，我们需要在获取博客ID后进行筛选
[140]   // 先获取所有匹配的ID
[141]   const ftsResult = await prisma.$queryRawUnsafe<Array<{ blogId: bigint; rank: number }>>(ftsQuery);
[142]   
[143]   if (ftsResult.length === 0) {
[144]     return {
[145]       blogs: [],
[146]       pagination: {
[147]         page,
[148]         limit,
[149]         total: 0,
[150]         totalPages: 0,
[151]         hasNext: false,
[152]         hasPrev: false,
[153]       },
[154]     };
[155]   }
[156]   
[157]   const blogIds = ftsResult.map(r => Number(r.blogId));
[158]   const rankMap = new Map(ftsResult.map(r => [Number(r.blogId), r.rank]));
[159]   
[160]   // 构建Prisma查询条件
[161]   const where: any = {
[162]     id: { in: blogIds },
[163]     status,
[164]   };
[165]   
[166]   if (categoryId) {
[167]     where.categoryId = categoryId;
[168]   }
[169]   
[170]   if (authorId) {
[171]     where.authorId = authorId;
[172]   }
[173]   
[174]   if (tagIds && tagIds.length > 0) {
[175]     where.blogTags = {
[176]       some: {
[177]         tagId: { in: tagIds },
[178]       },
[179]     };
[180]   }
[181]   
[182]   if (startDate || endDate) {
[183]     where.createdAt = {};
[184]     if (startDate) {
[185]       where.createdAt.gte = startDate;
[186]     }
[187]     if (endDate) {
[188]       where.createdAt.lte = endDate;
[189]     }
[190]   }
[191]   
[192]   // 计算总数（应用筛选条件后）
[193]   const total = await prisma.blog.count({ where });
[194]   
[195]   // 计算总页数
[196]   const totalPages = Math.ceil(total / limit);
[197]   
[198]   // 确定排序方式
[199]   let orderBy: any = {};
[200]   if (sort === 'relevance') {
[201]     // 按相关性排序：需要自定义排序逻辑
[202]     // 我们将按rank升序（FTS5 rank值越小越相关），但需要与筛选后的博客ID匹配
[203]     // 通过应用筛选后，我们仍然需要按rank排序，但rankMap只包含匹配的博客
[204]     // 我们将获取博客后手动排序
[205]   } else {
[206]     orderBy[sort] = order;
[207]   }
[208]   
[209]   // 获取博客列表
[210]   const blogs = await prisma.blog.findMany({
[211]     where,
[212]     skip: (page - 1) * limit,
[213]     take: limit,
[214]     orderBy: sort === 'relevance' ? undefined : orderBy,
[215]     include: {
[216]       author: {
[217]         select: {
[218]           id: true,
[219]           name: true,
[220]           email: true,
[221]           avatar: true,
[222]         },
[223]       },
[224]       category: {
[225]         select: {
[226]           id: true,
[227]           name: true,
[228]           slug: true,
[229]         },
[230]       },
[231]       blogTags: {
[232]         include: {
[233]           tag: {
[234]             select: {
[235]               id: true,
[236]               name: true,
[237]               slug: true,
[238]             },
[239]           },
[240]         },
[241]       },
[242]       _count: {
[243]         select: {
[244]           comments: true,
[245]           likes: true,
[246]           bookmarks: true,
[247]         },
[248]       },
[249]     },
[250]   });
[251]   
[252]   // 获取高亮片段
[253]   const snippets = await prisma.$queryRawUnsafe<Array<{ blogId: bigint; snippet: string }>>(`
[254]     SELECT blogId, snippet(BlogFTS, 2, '<b>', '</b>', '...', 120) as snippet
[255]     FROM BlogFTS
[256]     WHERE blogId IN (${blogIds.join(',')}) AND ${matchCondition}
[257]   `);
[258]   
[259]   const snippetMap = new Map(snippets.map(s => [Number(s.blogId), s.snippet]));
[260]   
[261]   // 格式化博客数据
[262]   const formattedBlogs: SearchBlogResult[] = blogs.map(blog => ({
[263]     id: blog.id,
[264]     title: blog.title,
[265]     excerpt: blog.excerpt,
[266]     content: blog.content,
[267]     snippet: snippetMap.get(blog.id) || '',
[268]     rank: rankMap.get(blog.id) || 0,
[269]     author: blog.author,
[270]     category: blog.category,
[271]     tags: blog.blogTags.map(blogTag => blogTag.tag),
[272]     status: blog.status,
[273]     createdAt: blog.createdAt,
[274]     updatedAt: blog.updatedAt,
[275]     publishedAt: blog.publishedAt,
[276]     viewCount: blog.viewCount,
[277]     _count: blog._count,
[278]   }));
[279]   
[280]   // 如果是按相关性排序，手动排序
[281]   if (sort === 'relevance') {
[282]     formattedBlogs.sort((a, b) => {
[283]       const rankA = a.rank;
[284]       const rankB = b.rank;
[285]       return order === 'asc' ? rankA - rankB : rankB - rankA;
[286]     });
[287]   }
[288]   
[289]   return {
[290]     blogs: formattedBlogs,
[291]     pagination: {
[292]       page,
[293]       limit,
[294]       total,
[295]       totalPages,
[296]       hasNext: page < totalPages,
[297]       hasPrev: page > 1,
[298]     },
[299]   };
[300] };
[301] 
[302] /**
[303]  * 获取搜索建议
[304]  */
[305] export const getSearchSuggestions = async (query: string): Promise<SearchSuggestion[]> => {
[306]   const suggestions: SearchSuggestion[] = [];
[307]   
[308]   if (!query || query.trim().length === 0) {
[309]     return suggestions;
[310]   }
[311]   
[312]   const searchQuery = query.trim();
[313]   
[314]   // 1. 从搜索历史中获取建议（最近5条）
[315]   const recentSearches = await prisma.searchHistory.findMany({
[316]     where: {
[317]       query: {
[318]         contains: searchQuery,
[319]         mode: 'insensitive',
[320]       },
[321]     },
[322]     orderBy: {
[323]       createdAt: 'desc',
[324]     },
[325]     take: 5,
[326]     distinct: ['query'],
[327]   });
[328]   
[329]   recentSearches.forEach(history => {
[330]     suggestions.push({
[331]       type: 'keyword',
[332]       text: history.query,
[333]     });
[334]   });
[335]   
[336]   // 2. 从标签中获取建议
[337]   const tagSuggestions = await prisma.tag.findMany({
[338]     where: {
[339]       name: {
[340]         contains: searchQuery,
[341]         mode: 'insensitive',
[342]       },
[343]     },
[344]     take: 5,
[345]   });
[346]   
[347]   tagSuggestions.forEach(tag => {
[348]     suggestions.push({
[349]       type: 'tag',
[350]       text: tag.name,
[351]       count: tag.blogCount,
[352]     });
[353]   });
[354]   
[355]   // 3. 从分类中获取建议
[356]   const categorySuggestions = await prisma.category.findMany({
[357]     where: {
[358]       name: {
[359]         contains: searchQuery,
[360]         mode: 'insensitive',
[361]       },
[362]     },
[363]     take: 5,
[364]   });
[365]   
[366]   categorySuggestions.forEach(category => {
[367]     suggestions.push({
[368]       type: 'category',
[369]       text: category.name,
[370]     });
[371]   });
[372]   
[373]   // 去重（相同文本和类型）
[374]   const seen = new Set<string>();
[375]   return suggestions.filter(suggestion => {
