[309] export const getSearchSuggestions = async (query: string): Promise<SearchSuggestion[]> => {
[310]   const suggestions: SearchSuggestion[] = [];
[311]   
[312]   if (!query || query.trim().length === 0) {
[313]     return suggestions;
[314]   }
[315]   
[316]   const searchQuery = query.trim();
[317]   
[318]   // 1. 从搜索历史中获取建议（最近5条）
[319]   const recentSearches = await prisma.searchHistory.findMany({
