[321]       query: {
[322]         contains: searchQuery,
[323]         mode: 'insensitive',
[324]       },
[325]     },
[326]     orderBy: {
[327]       createdAt: 'desc',
[328]     },
[329]     take: 5,
[330]     distinct: ['query'],
[331]   });
[332]   
[333]   recentSearches.forEach(history => {
[334]     suggestions.push({
[335]       type: 'keyword',
[336]       text: history.query,
[337]     });
[338]   });
[339]   
[340]   // 2. 从标签中获取建议
[341]   const tagSuggestions = await prisma.tag.findMany({
[342]     where: {
[343]       name: {
[344]         contains: searchQuery,
[345]         mode: 'insensitive',
[346]       },
[347]     },
[348]     take: 5,
[349]   });
[350]   
[351]   tagSuggestions.forEach(tag => {
[352]     suggestions.push({
[353]       type: 'tag',
[354]       text: tag.name,
[355]     });
[356]   });
[357]   
[358]   // 3. 从分类中获取建议
[359]   const categorySuggestions = await prisma.category.findMany({
[360]     where: {
[361]       name: {
[362]         contains: searchQuery,
[363]         mode: 'insensitive',
[364]       },
[365]     },
[366]     take: 5,
[367]   });
[368]   
[369]   categorySuggestions.forEach(category => {
[370]     suggestions.push({
[371]       type: 'category',
[372]       text: category.name,
[373]     });
[374]   });
[375]   
[376]   // 去重（相同文本和类型）
[377]   const seen = new Set<string>();
[378]   return suggestions.filter(suggestion => {
[379]     const key = `${suggestion.type}:${suggestion.text}`;
[380]     if (seen.has(key)) {
[381]       return false;
[382]     }
[383]     seen.add(key);
[384]     return true;
[385]   });
[386] };
