[445] /**
[446]  * 获取热门搜索关键词
[447]  */
[448] export const getPopularSearches = async (
[449]   period: 'today' | 'week' | 'month' | 'all' = 'today',
[450]   limit: number = 10
[451] ): Promise<PopularSearchItem[]> => {
[452]   // 构建日期筛选条件
[453]   let dateFilter = '';
[454]   const now = new Date();
[455]   
[456]   switch (period) {
[457]     case 'today':
[458]       const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());
[459]       dateFilter = `AND createdAt >= '${todayStart.toISOString()}'`;
[460]       break;
[461]     case 'week':
[462]       const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
[463]       dateFilter = `AND createdAt >= '${weekAgo.toISOString()}'`;
[464]       break;
[465]     case 'month':
[466]       const monthAgo = new Date(now.getFullYear(), now.getMonth() - 1, now.getDate());
[467]       dateFilter = `AND createdAt >= '${monthAgo.toISOString()}'`;
[468]       break;
[469]     case 'all':
[470]     default:
[471]       dateFilter = '';
[472]   }
[473]   
[474]   // 使用原始SQL进行聚合查询，但使用参数化查询避免SQL注入
[475]   const popularSearches = await prisma.$queryRaw<Array<{ query: string; count: bigint; lastSearched: Date }>>`
[476]     SELECT query, COUNT(*) as count, MAX(createdAt) as lastSearched
[477]     FROM SearchHistory
[478]     WHERE query IS NOT NULL AND query != '' ${dateFilter}
[479]     GROUP BY query
[480]     ORDER BY count DESC, lastSearched DESC
[481]     LIMIT ${limit}
[482]   `;
[483]   
[484]   return popularSearches.map(item => ({
[485]     query: item.query,
[486]     count: Number(item.count),
[487]     lastSearched: item.lastSearched,
[488]   }));
[489] };
