      const monthAgo = new Date(now.getFullYear(), now.getMonth() - 1, now.getDate());
      dateFilter = `AND createdAt >= '${monthAgo.toISOString()}'`;
      break;
    case 'all':
    default:
      dateFilter = '';
  }

  // 构建原始SQL查询字符串，使用参数化查询避免SQL注入
  const query = `SELECT query, COUNT(*) as count, MAX(createdAt) as lastSearched
    FROM SearchHistory
    WHERE query IS NOT NULL AND query != '' ${dateFilter}
    GROUP BY query
    ORDER BY count DESC, lastSearched DESC
    LIMIT ${limit}`;

  // 使用 $executeRaw 或 $queryRaw 执行原始查询
  const popularSearches = await prisma.$queryRawUnsafe(query);

  return popularSearches.map((item: any) => ({
    query: item.query,
    count: Number(item.count),
    lastSearched: item.lastSearched,
  }));
};'''

