const { PrismaClient } = require('@prisma/client');
const prisma = new PrismaClient();

async function main() {
  console.log('Creating BlogFTS virtual table...');
  try {
    await prisma.$executeRaw`CREATE VIRTUAL TABLE IF NOT EXISTS BlogFTS USING fts5(blogId, title, content, excerpt)`;
    console.log('BlogFTS table created successfully.');
    // 检查是否有数据，如果没有则从Blog表中插入
    const count = await prisma.$queryRaw`SELECT COUNT(*) as count FROM BlogFTS`;
    console.log('Current rows in BlogFTS:', count[0].count);
    if (count[0].count === 0) {
      console.log('Populating BlogFTS with existing blogs...');
      await prisma.$executeRaw`
        INSERT INTO BlogFTS (blogId, title, content, excerpt)
        SELECT id, title, content, excerpt FROM Blog
        WHERE status = 'PUBLISHED'
      `;
      console.log('Populated BlogFTS.');
    }
  } catch (error) {
    console.error('Error creating BlogFTS:', error);
  } finally {
    await prisma.$disconnect();
  }
}

main();

